// Both workflows use one schema, one source packet, and one completion standard.
const groups=[
{title:'Business & contacts',description:'Identify the business, its booking contact, public contact details, and service territory.',fields:{name:'Business name',contact:'Primary contact',email:'Booking email',phone:'Booking phone',address:'Business address',area:'Service territory',years:'Years in business',website:'Website / portfolio URL'}},
{title:'Services & fit',description:'Translate the interview into searchable services, fit criteria, and operating constraints.',fields:{services:'Services offered',style:'Style / specialty',capacity:'Event capacity / workload',coverage:'Standard coverage or service duration',team:'Team included',custom:'Customization options',exclusions:'Not included',requirements:'Venue / client requirements'}},
{title:'Packages & pricing',description:'Create three comparable package records, including inclusions and extra charges.',fields:{package1:'Entry package name',price:'Entry starting price',includes1:'Entry package inclusions',package2:'Signature package name',price2:'Signature starting price',includes2:'Signature package inclusions',package3:'Premium package name',price3:'Premium starting price',includes3:'Premium package inclusions',overtime:'Overtime / extra service rate',travel:'Travel charges',tax:'Tax / additional fees'}},
{title:'Logistics & policies',description:'Capture how a booking actually works, from deposit to delivery and cancellation.',fields:{deposit:'Booking deposit',balance:'Balance due',lead:'Recommended booking lead time',setup:'Setup / arrival requirements',delivery:'Delivery / fulfillment timeline',cancellation:'Cancellation policy',reschedule:'Rescheduling policy',backup:'Backup / contingency plan'}},
{title:'Portfolio & listing',description:'Write a public-facing listing and organize the work that demonstrates the vendor’s fit.',fields:{bio:'Public vendor bio',headline:'Listing headline',gallery:'Portfolio collections / links',featured:'Featured event description',credit:'Portfolio permission / credit',tags:'Search tags'}},
{title:'Checks & follow-up',description:'Record verification status honestly and follow up on information absent from the packet.',fields:{insurance:'Insurance certificate status',license:'License / permit status',reference:'Professional reference',followup:'Outstanding follow-up'}}
];
const allKeys=groups.flatMap(g=>Object.keys(g.fields));const total=allKeys.length;groups.forEach(g=>Object.assign(labels,g.fields));
const specifics={Photographer:{style:'Candid documentary; warm, true-to-life portraits',capacity:'One wedding per team per day; two teams maximum',coverage:'8 hours',team:'Lead photographer + second photographer',custom:'Extra coverage, albums, engagement sessions',exclusions:'Raw files, videography, and print products',requirements:'Family photo list; access to getting-ready rooms',package1:'The Keepsake',includes1:'8 hours; two photographers; online gallery; 600+ edited images',package2:'The Full Story',price2:'$5,800',includes2:'10 hours; two photographers; engagement session; 800+ images',package3:'The Heirloom',price3:'$7,200',includes3:'12 hours; engagement session; 10-inch album; 1,000+ images',overtime:'$350 / hour',setup:'Arrive 45 minutes before coverage starts',delivery:'Sneak peeks in 72 hours; full gallery in 8 weeks',backup:'Two camera bodies per photographer; dual-card recording; backup associate',featured:'120-guest outdoor ceremony at Juniper Grove; sunset portraits',tags:'Documentary, candid, Hill Country, warm color',headline:'The fleeting moments. Kept forever.'},DJ:{style:'Open-format dance music; collaborative playlist planning',capacity:'Up to 250 guests; one event per DJ per day',coverage:'6 hours',team:'One DJ / MC',custom:'Custom edits; uplighting; additional sound zones',exclusions:'Live musicians and stage rental',requirements:'Two dedicated 20A outlets; covered level performance area',package1:'Good Times',includes1:'6 hours DJ / MC; reception sound; planning call',package2:'Great Company',price2:'$3,200',includes2:'8 hours; ceremony sound; reception DJ / MC; dance lights',package3:'All Night',price3:'$4,100',includes3:'10 hours; ceremony and cocktail sound; uplighting; DJ / MC',overtime:'$250 / hour',setup:'90 minutes for sound check and setup',delivery:'Music plan finalized 14 days before event',backup:'Backup controller, laptop, and wireless microphone',featured:'200-guest downtown reception; disco and 2000s dance set',tags:'DJ, MC, open format, dance floor',headline:'For the one-more-song kind of night.'},Venue:{style:'Modern rustic; oak grove ceremony; indoor reception',capacity:'180 seated guests; 150 with indoor dance floor',coverage:'12-hour venue access',team:'One venue manager; client hires event coordinator',custom:'Furniture layouts; ceremony locations; vendor selection',exclusions:'Catering, alcohol, rentals beyond listed furniture',requirements:'Licensed caterer; insured vendors; shuttle plan for offsite guests',package1:'The Grove',includes1:'Friday or Sunday; 12-hour access; tables and chairs',package2:'The Celebration',price2:'$10,500',includes2:'Saturday; 12-hour access; suites; tables and chairs',package3:'The Weekend',price3:'$14,000',includes3:'Friday setup; Saturday event; Sunday collection window',overtime:'$500 / hour, subject to sound curfew',setup:'Vendor access from 10 a.m.; all collection by midnight',delivery:'Final floor plan due 30 days before event',backup:'Indoor ceremony option for up to 150 guests; generator hookup',featured:'150-guest spring wedding with indoor rain-plan ceremony',tags:'Venue, oak grove, indoor backup, Hill Country',headline:'Big skies. Your favorite people.'},Caterer:{style:'Texas barbecue with seasonal Southern sides',capacity:'50–250 guests; 50-guest minimum',coverage:'3-hour staffed dinner service',team:'Chef + one server per 25 guests',custom:'Vegetarian mains; gluten-free sides; late-night snacks',exclusions:'Alcohol, tables, linens, and china',requirements:'Potable water; covered prep area; loading access',package1:'Smokehouse',includes1:'Two meats; three sides; bread; disposable serviceware',package2:'Gather Round',price2:'$105 per guest',includes2:'Three meats; four sides; staffed buffet; dessert',package3:'The Whole Feast',price3:'$135 per guest',includes3:'Cocktail bites; three meats; four sides; dessert; china',overtime:'$45 per server / hour',setup:'Two-hour load-in; 45-minute breakdown',delivery:'Final menu and guaranteed guest count due 14 days before event',backup:'Backup warming equipment; alternate supplier; weather-protected buffet',featured:'180-guest ranch reception with vegetarian smoked-mushroom option',tags:'BBQ, Southern, buffet, vegetarian options',headline:'A feast worth gathering around.'}};
for(const [type,d]of Object.entries(samples)){Object.assign(d,{years:'8 years',website:`https://${d.name.toLowerCase().replace(/[^a-z]/g,'')}.example`,travel:'First 50 miles included; $2 / mile beyond, round trip',tax:'Sales tax added where applicable; no automatic gratuity',deposit:'30% non-refundable retainer',balance:'30 days before the event',lead:'9–12 months',cancellation:'Retainer is non-refundable; within 30 days the full balance is due',reschedule:'One date change within 12 months, subject to availability',gallery:`${d.name.toLowerCase().replace(/[^a-z]/g,'')}.example/portfolio; /collections/hill-country`,credit:'Vendor grants listing display permission; credit the vendor by business name',insurance:'Pending — certificate not supplied',license:'Vendor reports applicable licenses current; documentation not verified',reference:'Juniper Planning Co. — reference available on request',followup:'Request current liability insurance certificate and coverage expiry',...specifics[type]});}
let sectionIndex=0,sourceTab='call',reviewed=new Set(),decisions={price:false,delivery:false,insurance:false},packetViews=new Set(),manualStarted=null,aiStarted=null;const oldBind=bind,oldImport=importScreen,oldProfile=profile;
const origin={};groups.forEach((g,i)=>Object.keys(g.fields).forEach(k=>origin[k]=i===0?'website':i===1?'call':i===2?'rates':i===3?'call':i===4?'portfolio':'email'));origin.price='email';origin.delivery='email';origin.insurance='email';
const sourceNames={call:'Interview notes',website:'Vendor website',rates:'Rate card',portfolio:'Portfolio',email:'Follow-up email'};
function evidenceValue(k){if(k==='insurance')return 'No certificate attached. Vendor says: “I’ll send it over separately.”';if(k==='followup')return 'Current insurance certificate and expiry date have not been supplied.';return samples[state.type][k]}
function packetBody(tab){const d=samples[state.type];if(tab==='website')return `<strong>${esc(d.name)} · About & contact</strong>\n\n${esc(d.bio)}\n\nBased at ${esc(d.address)}. We serve ${esc(d.area)}.\n\nBookings: ${esc(d.contact)}\n${esc(d.email)} · ${esc(d.phone)}\n${esc(d.website)}\nEstablished ${esc(d.years)} ago.\n\n<strong>Packages from ${state.type==='Caterer'?'$75 per guest':state.type==='Venue'?'$7,500':state.type==='DJ'?'$2,000':'$3,800'}</strong>\nThis public page has not yet been updated for the new season.\n\n<strong>What we do</strong>\n${esc(d.services)}\n\n<strong>Delivery / fulfillment</strong>\n${state.type==='Photographer'?'Full galleries delivered in 6 weeks.': 'Ask us for the latest delivery / planning deadline.'}`;
if(tab==='rates')return `<strong>2027 vendor rate card · Internal attachment</strong>\n\n${['package1','price','includes1','package2','price2','includes2','package3','price3','includes3','overtime','travel','tax'].map(k=>`${esc(labels[k])}: ${esc(d[k])}`).join('\n\n')}\n\nCustom quotes depend on scope. Record package inclusions separately so couples can compare fairly. Website pricing may reflect the prior season.`;
if(tab==='portfolio')return `<strong>Portfolio / listing brief</strong>\n\n${['headline','gallery','featured','credit','tags'].map(k=>`${esc(labels[k])}: ${esc(d[k])}`).join('\n\n')}\n\n<strong>Public bio source</strong>\n${esc(d.bio)}\n\nRep task: turn the conversational description into a concise public bio; preserve the facts. Do not imply that platform approval verifies permissions.`;
if(tab==='email')return `<strong>Subject: A couple of updates before we go live</strong>\nFrom: ${esc(d.contact)}\n\nThanks for the call! Please use ${esc(d.price)} as the entry starting price for the new season. The public website is still showing our previous rate. The attached rate card has the current package details.\n\nFor the timeline, use: ${esc(d.delivery)}. ${state.type==='Photographer'?'The old website still says six weeks, but that is no longer our standard.':'The intake note that says “confirm at booking” is incomplete.'}\n\nOur applicable licenses are current, as discussed, but I haven’t sent supporting documents yet. For insurance, I’ll send the certificate separately.\n\nJuniper Planning Co. can be a reference if needed.\n\n${esc(d.contact)}\n\n<strong>Attachments: rate-card.txt only. No insurance certificate attached.</strong>`;
return `<strong>Rep interview · Unstructured notes</strong>\nFictional source packet · No live call is taking place\n\nREP: Before we list you, talk me through your ideal wedding and what you bring.\nVENDOR: ${esc(d.style)}. We offer ${esc(d.services)}. Capacity is ${esc(d.capacity)}.\n\nREP: How does the standard booking work?\nVENDOR: ${esc(d.coverage)}. ${esc(d.team)}. We can customize with ${esc(d.custom)}. We don’t include ${esc(d.exclusions)}. We need ${esc(d.requirements)}.\n\nREP: What about the payment schedule and changes?\nVENDOR: ${esc(d.deposit)} to reserve the date, and the rest ${esc(d.balance)}. Recommend booking ${esc(d.lead)} ahead. ${esc(d.cancellation)}. ${esc(d.reschedule)}.\n\nREP: Walk me through event day and delivery.\nVENDOR: ${esc(d.setup)}. Timeline: ${state.type==='Photographer'?'I think the website says six weeks—let me confirm by email.':'Confirm final timeline at booking; I’ll email the actual deadline.'} For contingencies: ${esc(d.backup)}.\n\nREP: How long have you been doing this?\nVENDOR: ${esc(d.years)}. Our work is at ${esc(d.website)}. Ask ${esc(d.contact)} about dates. The rate card breaks down three packages, overtime, travel, and fees.\n\nREP: Anything to verify?\nVENDOR: Licenses are current, but I haven’t sent the paperwork. I’ll email the insurance certificate separately. Juniper Planning Co. can provide a reference.\n\nREP NOTE: Follow up on price mismatch, delivery timeline, and missing certificate. Need a public bio, structured package records, searchable tags, and complete booking policies.`}
function packetPanel(){return `<section class="card source-panel"><span class="eyebrow">THE SAME SOURCE PACKET IN BOTH FLOWS</span><h2 style="margin-top:12px">Find the details. Connect the dots.</h2><p style="font-size:11px">Five fictional sources. Information is scattered, repeated, and sometimes out of date.</p><div class="source-tabs">${Object.entries(sourceNames).map(([k,v])=>`<button data-source-tab="${k}" class="${sourceTab===k?'selected':''}">${v}</button>`).join('')}</div><div class="source-document">${packetBody(sourceTab)}</div><div class="notice">${state.mode==='before'?'Read the sources and organize the answers into the onboarding record. Copy and paste is allowed. No artificial wait timers.':'AI drafts from these same sources. Inspect evidence and confirm the exceptions.'}</div></section>`}
function completed(obj){return allKeys.filter(k=>String(obj[k]||'').trim()).length}
intro=function(){return `<div class="intro"><div><span class="tag">${state.mode==='before'?'THE MANUAL PROCESS':'✧ AUTOMATED ONBOARDING'}</span><h2 style="margin-top:14px">${state.mode==='before'?'The work is in making sense of it all.':'Same onboarding standard. Less assembly work.'}</h2><p>${state.mode==='before'?'Read five sources, structure three packages, write the listing, and reconcile conflicting details.':'Draft the complete record from the source packet, then check the details and resolve exceptions.'}</p></div><div class="big-stat">${total}<small>DETAILS · 6 SECTIONS · 5 SOURCES</small></div></div>`};
function sectionNav(auto){return `<div class="section-nav" aria-label="Onboarding sections">${groups.map((g,i)=>`<button class="${sectionIndex===i?'selected':''}" data-section="${i}">${i+1}. ${g.title}<small>${auto?(reviewed.has(i)?'✓':'Review'):Object.keys(g.fields).filter(k=>state.manual[k]?.trim()).length+'/'+Object.keys(g.fields).length}</small></button>`).join('')}</div>`}
function workflowField(k,auto){const value=(auto?state.data:state.manual)[k]||'';const long=['services','style','custom','exclusions','requirements','includes1','includes2','includes3','travel','tax','setup','delivery','cancellation','reschedule','backup','bio','gallery','featured','credit','followup'].includes(k);return `<div class="field ${long?'full':''}"><label for="wf-${k}">${esc(labels[k])}</label>${long?`<textarea id="wf-${k}" data-work-key="${k}" placeholder="${auto?'Review draft':'Find, organize, and enter details'}">${esc(value)}</textarea>`:`<input id="wf-${k}" data-work-key="${k}" value="${esc(value)}" placeholder="Enter ${esc(labels[k]).toLowerCase()}">`}${auto?`<div class="evidence"><span>${k==='insurance'?'⚑ Missing documentation':k==='bio'?'✧ Draft for review':'Source-backed draft'}</span><button data-evidence="${k}">${sourceNames[origin[k]]} ↗</button></div>`:''}</div>`}
manualScreen=function(){if(!manualStarted)manualStarted=Date.now();const g=groups[sectionIndex];return `<div class="work-summary"><div><strong id="manual-count">${completed(state.manual)} / ${total} details entered</strong><small>6 sections · 3 packages · 3 exceptions to reconcile</small></div><div><strong>No shortcuts hidden in the clock.</strong><small>Switch sections freely. Sources are available beside the worksheet.</small></div></div>${sectionNav(false)}<div class="workbench"><section class="card"><div class="card-head"><div><span class="eyebrow">MANUAL WORKSHEET · ${sectionIndex+1} / 6</span><h2 style="margin-top:10px">${g.title}</h2></div><select id="work-type" aria-label="Vendor category" style="width:150px">${Object.keys(samples).map(t=>`<option ${t===state.type?'selected':''}>${t}</option>`).join('')}</select></div><p class="section-description">${g.description}</p>${sectionIndex===5?`<div class="warning"><b>Before marking this record ready</b><p>The website and email disagree on price and delivery. The insurance certificate is missing. Record the current facts and outstanding work; never invent verification.</p></div>`:''}<div class="fields">${Object.keys(g.fields).map(k=>workflowField(k,false)).join('')}</div><div class="footer"><button class="secondary" data-prev ${sectionIndex===0?'disabled':''}>← Previous</button>${sectionIndex<5?'<button class="primary" data-next>Next section →</button>':'<button class="primary" id="finish-manual">Check completeness →</button>'}</div><div class="notice">Manual draft is kept while you explore this session. This is an onboarding exercise, not a test of typing speed.</div><button class="text-btn" onclick="sectionIndex=0;start('after')" style="margin-top:15px">See AI assemble the same record →</button></section>${packetPanel()}</div>`};
importScreen=function(){return `<div class="workflow-banner"><b>The task: build a complete, usable vendor record.</b><br>Business information, services and constraints, three priced packages, booking policies, a public listing, and verification follow-up. Both workflows use the same ${total}-detail checklist.</div>`+oldImport().replace('We’ll take it from there.','The demo loads a five-source packet for your selected vendor.').replace('Links and transcripts demonstrate the input flow; extracted results use the selected fictional vendor sample.','Links and transcripts demonstrate the input flow. Results use a five-source fictional packet, including a rate card and follow-up email. No live extraction occurs.')};
function decisionCards(){return `<div class="decision ${decisions.price?'resolved':''}"><b>${decisions.price?'✓':'⚑'} Starting price differs across sources</b><p>The website shows last season’s rate. The follow-up email and rate card specify ${esc(samples[state.type].price)}.</p><button class="secondary" data-decision="price">${decisions.price?'Confirmed: current rate':'Use current email / rate card'}</button><button class="text-btn" data-evidence="price">Read evidence</button></div><div class="decision ${decisions.delivery?'resolved':''}"><b>${decisions.delivery?'✓':'⚑'} Delivery / planning timeline needs reconciliation</b><p>Interview notes ${state.type==='Photographer'?'repeat an old six-week timeline':'leave the deadline unspecified'}. The follow-up email gives: ${esc(samples[state.type].delivery)}.</p><button class="secondary" data-decision="delivery">${decisions.delivery?'Confirmed: email timeline':'Use confirmed email timeline'}</button><button class="text-btn" data-evidence="delivery">Read evidence</button></div><div class="decision ${decisions.insurance?'resolved':''}"><b>${decisions.insurance?'✓':'⚑'} Insurance certificate absent</b><p>AI cannot verify a document that was never supplied. Keep this vendor pending verification and prepare a focused follow-up.</p><button class="secondary" data-decision="insurance">${decisions.insurance?'Acknowledged: verification pending':'Keep pending & prepare follow-up'}</button></div>${decisions.insurance?`<label for="followup-draft">Follow-up draft · never sent by this demo</label><textarea id="followup-draft" class="followup">Hi ${esc(samples[state.type].contact)},\n\nThanks for confirming the current pricing and timeline. Before we can mark your vendor record verified, please send your current liability insurance certificate showing coverage and expiry, and supporting license / permit documentation where applicable.\n\nThanks,\nJamie · I Do! vendor success</textarea><button class="text-btn" id="copy-followup">Copy draft</button>`:''}`}
reviewScreen=function(){if(!aiStarted){aiStarted=Date.now();reviewed.clear();decisions={price:false,delivery:false,insurance:false}}const g=groups[sectionIndex];return `${steps()}<div class="work-summary"><div><strong>${total} details drafted from 5 sources</strong><small>3 packages structured · 2 conflicts surfaced · 1 missing certificate flagged</small></div><div><strong>${reviewed.size} / 6 sections reviewed</strong><small>Drafted information still needs your judgment.</small></div></div>${sectionNav(true)}<div class="workbench"><section class="card"><span class="eyebrow">REVIEW THE SAME ONBOARDING RECORD</span><h2 style="margin-top:10px">${g.title}</h2><p class="section-description">${g.description}</p>${sectionIndex===5?decisionCards():''}<div class="fields">${Object.keys(g.fields).map(k=>workflowField(k,true)).join('')}</div><div class="review-check"><input id="review-section" type="checkbox" ${reviewed.has(sectionIndex)?'checked':''}><label for="review-section">I reviewed this section’s details and source evidence. Marking reviewed does not verify the vendor’s documents.</label></div><div class="footer"><button class="secondary" data-prev ${sectionIndex===0?'disabled':''}>← Previous</button>${sectionIndex<5?'<button class="primary" data-next>Next section →</button>':`<button class="primary" id="finish-ai" ${reviewed.size===6&&Object.values(decisions).every(Boolean)?'':'disabled'}>Save reviewed record →</button>`}</div>${sectionIndex===5?`<p style="font-size:11px">Review all six sections and acknowledge all three exceptions to save. This record will remain pending documentation.</p>`:''}</section>${packetPanel()}</div>`};
profile=function(){return `${steps()}<div class="workflow-banner"><b>✓ Record assembled and reviewed. Verification still pending.</b><br>${total} details across 6 sections. Current price and timeline confirmed; insurance and license documents still require vendor follow-up.</div><div class="heading"><div><span class="eyebrow">${esc(state.type)} · REVIEWED VENDOR RECORD</span><h1>${esc(state.data.name)}</h1><p>${esc(state.data.bio)}</p></div><span class="pill pending">Pending documentation</span></div><div class="snapshot-grid">${groups.map(g=>`<section class="card"><h3>${g.title}</h3>${Object.keys(g.fields).map(k=>`<div class="snapshot-row"><small>${esc(labels[k])}</small>${esc(state.data[k]||'Not captured in earlier demo')}</div>`).join('')}</section>`).join('')}</div><div class="footer"><button class="secondary" id="export">Export complete record ↓</button><button class="primary" onclick="sectionIndex=0;aiStarted=null;state.url='';start('after')">Onboard another vendor →</button></div>`};
impact=function(){return heading('Show the work. Then measure the difference.','One source packet. One onboarding standard. Two ways to complete it.')+`<div class="workflow-banner">This scenario compares the information-processing work: finding facts, structuring packages, reconciling versions, drafting a listing, and identifying missing documentation.</div><div class="metrics"><div class="metric"><small>SHARED REQUIREMENTS</small><strong>${total} details</strong><small>Across six onboarding sections</small></div><div class="metric"><small>SHARED INPUTS</small><strong>5 sources</strong><small>Interview, website, rates, portfolio, email</small></div><div class="metric"><small>HUMAN JUDGMENT</small><strong>3 exceptions</strong><small>Price, timeline, missing insurance</small></div></div><div class="comparison-cols"><section class="card"><span class="tag manual-note">BEFORE · REP ASSEMBLES</span><h2 style="margin-top:16px">Gather, interpret, re-enter.</h2><ol><li>Read the five source documents.</li><li>Find and map ${total} details to the schema.</li><li>Structure three packages with inclusions.</li><li>Resolve outdated price and timeline.</li><li>Draft public bio and search tags.</li><li>Identify missing proof and write follow-up.</li><li>Check the complete record.</li></ol><button class="secondary" onclick="sectionIndex=0;start('before')">Try the manual workflow →</button></section><section class="card"><span class="tag">AFTER · REP REVIEWS</span><h2 style="margin-top:16px">Import, check, decide.</h2><ol><li>Provide the source packet.</li><li>Receive a structured draft of the same record.</li><li>Inspect evidence and edit each section.</li><li>Confirm the two conflicting facts.</li><li>Acknowledge missing proof and review follow-up.</li><li>Save a reviewed record, pending documentation.</li></ol><button class="primary" onclick="sectionIndex=0;aiStarted=null;start('after')">Try the automated workflow →</button></section></div><section class="card" style="margin-top:22px"><h2>A credible demo isn’t a performance study.</h2><p>Both paths use the same task, allow copy and paste, and have no forced delays. The AI extraction is simulated; its short animation is not an inference benchmark.</p><p>To establish a real speed claim, time reps completing the same full task with and without a working extraction system. Compare active work time, corrections, missing fields, and follow-up quality. Vendor response time remains outside either workflow.</p></section>`};
showSource=function(k){sourceTab=origin[k]||'call';$('#source-title').textContent=labels[k];$('#source-copy').textContent=(k==='price'?`Old website rate conflicts with current rate card and follow-up email. Current starting price: ${samples[state.type].price}.\n\n`:k==='delivery'?`Interview / website has an old or incomplete timeline. Follow-up email confirms: ${samples[state.type].delivery}.\n\n`:'')+`${sourceNames[sourceTab]} · fictional packet\n\n${evidenceValue(k)}\n\nInspect the full source packet beside the worksheet. This demonstrates attribution, not live extraction or independent verification.`;$('#source').showModal()};
bind=function(){oldBind();document.querySelectorAll('[data-source-tab]').forEach(b=>b.onclick=()=>{sourceTab=b.dataset.sourceTab;packetViews.add(sourceTab);render()});document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{sectionIndex=+b.dataset.section;render()});document.querySelectorAll('[data-work-key]').forEach(e=>e.oninput=()=>{const auto=state.mode==='after';(auto?state.data:state.manual)[e.dataset.workKey]=e.value;if(auto){reviewed.delete(sectionIndex);if($('#review-section'))$('#review-section').checked=false;if($('#finish-ai'))$('#finish-ai').disabled=true}else if($('#manual-count'))$('#manual-count').textContent=`${completed(state.manual)} / ${total} details entered`});document.querySelectorAll('[data-prev]').forEach(b=>b.onclick=()=>{sectionIndex=Math.max(0,sectionIndex-1);render()});document.querySelectorAll('[data-next]').forEach(b=>b.onclick=()=>{sectionIndex=Math.min(5,sectionIndex+1);render();window.scrollTo(0,0)});document.querySelectorAll('[data-evidence]').forEach(b=>b.onclick=()=>showSource(b.dataset.evidence));if($('#work-type'))$('#work-type').onchange=e=>{state.type=e.target.value;state.manual={};sectionIndex=0;render()};if($('#review-section'))$('#review-section').onchange=e=>{e.target.checked?reviewed.add(sectionIndex):reviewed.delete(sectionIndex);render()};document.querySelectorAll('[data-decision]').forEach(b=>b.onclick=()=>{const k=b.dataset.decision;decisions[k]=true;if(k==='price'||k==='delivery')state.data[k]=samples[state.type][k];else{state.data.insurance='Pending — certificate requested, not verified';state.data.followup='Request insurance certificate, coverage expiry, and supporting license documents; draft prepared, not sent'}reviewed.delete(5);render()});if($('#finish-manual'))$('#finish-manual').onclick=()=>{const missing=allKeys.filter(k=>!state.manual[k]?.trim());if(missing.length){$('#source-title').textContent=`${missing.length} details still need attention`;$('#source-copy').textContent=groups.map(g=>{const keys=Object.keys(g.fields).filter(k=>missing.includes(k));return keys.length?g.title+': '+keys.map(k=>labels[k]).join(', '):''}).filter(Boolean).join('\n\n')+'\n\nUse “Pending / not supplied” for missing evidence. Do not invent it.';$('#source').showModal()}else{toast('Manual record complete. Review conflicts and document status before handoff.');state.data={...state.manual};state.step=3;state.mode='after';render()}};if($('#finish-ai'))$('#finish-ai').onclick=()=>{if(reviewed.size!==6||!Object.values(decisions).every(Boolean))return;if(completed(state.data)!==total){toast('Complete all details, or explicitly record missing information.');return}state.data.recordStatus='Pending documentation';saved=saved.filter(v=>v.data.name!==state.data.name);saved.push({type:state.type,data:{...state.data}});try{localStorage.setItem('bubs-vendors',JSON.stringify(saved))}catch{}state.step=3;render();window.scrollTo(0,0)};if($('#copy-followup'))$('#copy-followup').onclick=async()=>{try{await navigator.clipboard.writeText($('#followup-draft').value);toast('Follow-up copied. Nothing was sent.')}catch{toast('Select the draft text to copy it.')}};if($('#extract')){const original=$('#extract').onclick;$('#extract').onclick=()=>{sectionIndex=0;aiStarted=null;original()}};document.querySelectorAll('[data-mode]').forEach(b=>{const original=b.onclick;b.onclick=()=>{sectionIndex=0;original()}});if($('#export'))$('#export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({category:state.type,...state.data},null,2)],{type:'application/json'}));a.download='bubs-complete-onboarding.json';a.click();URL.revokeObjectURL(a.href)};};
// Make the directory reflect documentation state rather than imply verification.
const originalDirectory=directory;directory=function(){return originalDirectory().replaceAll('Approved','Reviewed').replaceAll('approved','reviewed').replaceAll('<span class="pill">Reviewed</span>','<span class="pill pending">Pending docs</span>')};
render();

